def bellman_ford(graph, src):
    """
    Bellman-Ford algorithm to find the shortest paths from a single source vertex to all other vertices
    in a weighted graph. The graph can contain negative edge weights and negative weight cycles.

    :param graph: A dictionary representing the graph where keys are vertices and values are dictionaries
                  of adjacent vertices and corresponding weights.
    :param src: The source vertex.
    :return: The distances from the source vertex to all other vertices. If a negative weight cycle is detected,
             it returns None.
    """
    # Step 1: Initialize distances and predecessors
    V = len(graph)
    distances = {v: float('inf') for v in graph}
    distances[src] = 0
    predecessors = {v: None for v in graph}

    # Step 2: Relax edges repeatedly
    for _ in range(V - 1):
        for u in graph:
            for v in graph[u]:
                if distances[u] + graph[u][v] < distances[v]:
                    distances[v] = distances[u] + graph[u][v]
                    predecessors[v] = u

    # Step 3: Check for negative weight cycles
    for u in graph:
        for v in graph[u]:
            if distances[u] + graph[u][v] < distances[v]:
                raise ValueError("Graph contains a negative weight cycle")

    return distances

